            r = r * i % MOD
        return r

    def invFact(x):
        return power(fact(x), MOD - 2)

    def binom(n, k):
        if k < 0 or k > n:
            return 0
        return fact(n) * invFact(k) % MOD * invFact(n - k) % MOD

    ans = 0
    for try_val in range(1, n + 1):
        r = n - try_val + 1
        term = power(try_val, r) * binom(n, k) % MOD
        ans = (ans + term) % MOD

    ans = ans * fact(k) % MOD
    return str(ans + 0)

