            return 0
        s = str(n)
        return len(s)

    def sum_digits(n):
        count = 0
        for i in range(1, n + 1):
            count += digit_count(i)
        return count

    def count_digits_upto_len(L, n_digits):
        # Count total number of digits in numbers with 1 to n_digits digits
        if n_digits < 1:
            return 0
        start = 10 ** (n_digits - 1)
        if start > L:
            return 0
        end = min(L, 10 ** n_digits - 1)
        return n_digits * (end - start + 1)

    def find_digit_for_1_to_n(n):
        # Total number of digits if we write all numbers from 1 to n
        if n == 0:
            return 0
        result = 0
        d = 1
        while True:
            start = 10 ** (d - 1)
            end = min(n, 10 ** d - 1)
            if start > end:
                break
            count = end - start + 1
            result += count * d
            d += 1
            if d > 18:
                break
        return result

    def find_block_for_k(k):
        total_len = 0
        n = 1
        while True:
            digits_in_block = sum(digit_count(i) for i in range(1, n + 1))
            if k <= total_len + digits_in_block:
                return n
            total_len += digits_in_block
            n += 1
            if n > 10**14:
                break
        return n

    def find_number_in_block(k, block_len):
        remaining = k
        n = 1
        while True:
            d = digit_count(n)
            if remaining <= d:
                return n, remaining - 1
            remaining -= d
            n += 1
        return n, 0

    results = []
    for k in queries:
        # Find which block k is in
        total_len = 0
        block_num = 1
        while True:
            digits_in_block = 0
            i = 1
            while i <= block_num:
                digits_in_block += digit_count(i)
                i += 1
            if k <= total_len + digits_in_block:
                break
            total_len += digits_in_block
            block_num += 1

        k -= total_len
