    def ask(h, w, r1, c1, r2, c2):
        nonlocal query_count
        if query_count >= 3 * (int(__import__('math').math.log2(n + m)) + 1):
            return 0
        query_count += 1

        for i in range(r1, r1 + h):
            for j in range(c1, c1 + w):
                if (i, j) in sim_matrix:
                    if sim_matrix[(i, j)] - (r2 * h + c2 * w) < 0:
                        return 0
                else:
                    return 0

        for i in range(r2, r2 + h):
            for j in range(c2, c2 + w):
                if (i, j) in sim_matrix:
                    if sim_matrix[(i, j)] - (r1 * h + c1 * w) < 0:
                        return 0
                else:
                    return 0

        return 1

