def count_constraints(n, constraints):
    if not constraints:
        return 1 << n

    target_code, target_count = constraints[0]
    nbits = len(target_code)

    count = 0
    for positions in combinations(range(nbits), target_count):
        mask = 0
        for pos in positions:
            mask |= 1 << pos

        for constraint_code, response in constraints[1:]:
            bits = sum((mask >> i) & 1 for i in range(nbits))
            temp = 0
            for i in range(nbits):
                if constraint_code[i] == '1':
                    temp |= 1 << i

            if bin(mask & temp).count('1') != response:
                break
        else:
            count += 1

    return count

